@import url("https://fonts.googleapis.com/css2?family=Geist:wght@300;400;500;600&family=Geist+Mono:wght@400;500&display=swap");
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Liquid Glass — by Bilal Gürsen, https://github.com/bilalgursen/liquid-glass (MIT).
 *
 * A quiet neutral stage under controls made of clear glass. Every button, card,
 * badge, tab lens, switch, checkbox and slider is a WebGL lens that bends and
 * frosts what lies behind it and swells on wobbly springs under the pointer.
 * Colour lives only behind the glass; the chrome stays near-white with hairline
 * rules. Geist carries every label. Tokens are taken from the kit's own
 * stylesheet (src/styles.css) and its control tokens (controls/glass/tokens.ts).
 */

:root {
  --background: oklch(0.988 0.001 286.4);
  --foreground: oklch(0.15 0.002 286.1);

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.15 0.002 286.1);
  --popover: oklch(0.988 0.001 286.4);
  --popover-foreground: oklch(0.15 0.002 286.1);

  /* The kit's blue at a depth white text reads on (4.5:1). The glass controls
     keep the kit's brighter --glass-accent for their fills. */
  --primary: oklch(0.516 0.188 261.2);
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(0.965 0.003 286.3);
  --secondary-foreground: oklch(0.15 0.002 286.1);
  --muted: oklch(0.965 0.003 286.3);
  --muted-foreground: oklch(0.513 0.012 286);
  --accent: oklch(0.965 0.003 286.3);
  --accent-foreground: oklch(0.15 0.002 286.1);

  --destructive: oklch(0.508 0.18 11.7);
  --destructive-foreground: oklch(1 0 0);
  --success: oklch(0.492 0.115 158);
  --success-foreground: oklch(1 0 0);
  --warning: oklch(0.515 0.122 59.3);
  --warning-foreground: oklch(1 0 0);

  --border: oklch(0 0 0 / 0.08);
  /* The well of a text field: frosted white on the stage. */
  --input: oklch(1 0 0 / 0.72);
  --ring: oklch(0.63 0.185 254.9);

  /* The stage the glass sits on, and what the canvas controls bend where
     nothing is drawn beneath them. */
  --stage: oklch(0.944 0.003 286.3);
  --glass-surface: var(--stage);
  /* The kit's control accent (switch track, checkbox fill, slider fill). */
  --glass-accent: oklch(0.658 0.185 255);
  /* Frosted glass before WebGL draws, and for surfaces that stay CSS. */
  --glass-fill: oklch(1 0 0 / 0.6);
  --glass-rim: oklch(1 0 0 / 0.6);
  --glass-wash: oklch(0 0 0 / 0.05);
  --track: oklch(0.825 0.006 297.7);
  /* A filled rating star. */
  --rating: oklch(0.828 0.189 84.4);

  --radius: 1rem;

  --font-sans: "Geist", ui-sans-serif, system-ui, -apple-system, "Segoe UI",
    sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SF Mono", Menlo, Consolas,
    monospace;

  /* The card's own drop shadow from the kit: two soft layers under the glass. */
  --shadow-glass: 0 1.03rem 2.25rem oklch(0 0 0 / 0.08),
    0 1.65rem 3.49rem oklch(0 0 0 / 0.08);
  --shadow-xs: 0 0.0625rem 0.125rem oklch(0 0 0 / 0.05);
  --shadow-sm: 0 0.0625rem 0.1875rem oklch(0 0 0 / 0.08);
  --shadow-md: 0 0.5rem 1.5rem oklch(0 0 0 / 0.08),
    0 0.125rem 0.375rem oklch(0 0 0 / 0.05);
  --shadow-lg: var(--shadow-glass);
  --shadow-s: var(--shadow-sm);
  --shadow-m: var(--shadow-md);
  --shadow-l: var(--shadow-glass);
  --shadow-inset: inset 0 0.0625rem 0.125rem oklch(0 0 0 / 0.05);
  --shadow-button: 0 0 0 0.0625rem var(--glass-rim), var(--shadow-sm);
  --shadow-button-hover: 0 0 0 0.0625rem var(--glass-rim), var(--shadow-md);
  --shadow-primary: var(--shadow-sm);
  --shadow-knob: 0 0.0625rem 0.25rem oklch(0 0 0 / 0.16);
  --knob-on: var(--glass-accent);
  --surface-on: var(--glass-accent);

  --chart-1: oklch(0.658 0.185 255);
  --chart-2: oklch(0.516 0.188 261.2);
  --chart-3: oklch(0.72 0.13 200);
  --chart-4: oklch(0.6 0.16 290);
  --chart-5: oklch(0.8 0.1 230);

  /* Motion: the soft profile for glass systems. Its in-out curve is the kit's
     own; the glass itself moves on the kit's springs, not on these. */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  --radius-sm: calc(var(--radius) - 0.5rem);
  --radius-md: calc(var(--radius) - 0.375rem);
  --radius-lg: calc(var(--radius) - 0.25rem);
  --radius-xl: var(--radius);
  --radius-2xl: calc(var(--radius) + 0.25rem);
  --radius-3xl: calc(var(--radius) + 0.75rem);

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-glass: var(--shadow-glass);
  --shadow-inset: var(--shadow-inset);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --shadow-knob: var(--shadow-knob);

  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  --ease-out: var(--ease-out);
  --ease-in-out: var(--ease-in-out);
  --ease-drawer: var(--ease-drawer);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-family: var(--font-sans);
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  button,
  a {
    -webkit-tap-highlight-color: transparent;
  }

  textarea {
    resize: vertical;
  }

  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

/* The kit's press: 0.96 over 150ms, never when disabled. It carries the whole
   transition list, so it is the only transition utility a control needs. */
@utility press {
  transition-property: color, background-color, border-color, box-shadow, opacity, scale;
  transition-duration: 150ms;
  transition-timing-function: ease-out;
  &:not(:disabled):active {
    scale: 0.96;
  }
  @media (prefers-reduced-motion: reduce) {
    &:not(:disabled):active {
      scale: 1;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: comfortable;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 56);
  --layout-inset: calc(var(--spacing, 0.25rem) * 6);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 8);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 5);
}

